window.mountNeonMindInquiry=function(root=document){const form=root.querySelector('#inquiry'),status=root.querySelector('#status');if(!form||form.dataset.mounted)return;form.dataset.mounted='true';form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='Deine Anfrage wird übertragen …';try{const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;const r=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const b=await r.json();if(!r.ok)throw Error(b.error||'Die Anfrage konnte nicht gespeichert werden.');form.reset();status.textContent='Deine Anfrage ist in unserer Shop-Verwaltung eingegangen. Referenz: '+b.id+'\nBitte bewahre diese Referenz auf. Wir senden dir eine Eingangsbestätigung per E-Mail.';}catch(e){status.textContent=e.message+' Deine Eingaben bleiben erhalten.';}finally{button.disabled=false;}});
const requested=new URLSearchParams(location.search).get('produkt');if(requested&&/^[a-z0-9-]{1,48}$/.test(requested)){fetch('/api/products').then(r=>r.json()).then(items=>{const item=items.find(p=>p.id===requested);if(item)form.elements.product.value=item.name;}).catch(()=>{form.elements.product.value=requested;});}

};window.mountNeonMindInquiry();
